const fs = require('node:fs');
const path = require('node:path');

const source = path.resolve(__dirname, '../../server/workflowContract.js');
const workflow = require(source);
const assignableStates = [...new Set([...workflow.WORK_ITEM_STATE_LIST, ...Object.keys(workflow.LEGACY_WORK_ITEM_STATE_MAP)])]
    .filter(status => status === 'ASSIGNED' || workflow.isValidWorkItemTransition(status, 'ASSIGNED'));

const outputs = {
    'workflowContract.js': fs.readFileSync(source),
    'assignmentWorkflow.js': Buffer.from([
        '// Generated by scripts/generate-workflow-contract.cjs from server/workflowContract.js.',
        'export const ASSIGNABLE_WORK_ITEM_STATES = Object.freeze(' + JSON.stringify(assignableStates) + ');',
        'export const CLOSURE_TASK_ANALYSES = Object.freeze(' + JSON.stringify(workflow.CLOSURE_TASK_ANALYSES) + ');',
        ''
    ].join('\n'))
};

for (const [filename, expected] of Object.entries(outputs)) {
    const target = path.resolve(__dirname, '../src/utils', filename);
    const current = fs.existsSync(target) ? fs.readFileSync(target) : Buffer.alloc(0);
    if (expected.equals(current)) continue;
    if (process.argv.includes('--check')) {
        console.error('Generated ' + filename + ' differs from the server. Run the client build generator.');
        process.exitCode = 1;
    } else {
        fs.writeFileSync(target, expected);
    }
}
